// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Font Loading
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadGothic = makeLoadFont('UnifrakturMaguntia');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: gothicFamily } = loadGothic();



export type AdAnimationProps = Record<string, any>;

// Static configuration for the blood drips - expanded for a much heavier bleed effect
const dripsData = [
  { x: 5, w: 1.2, delay: 18, maxH: 0.05, drop: false },
  { x: 12, w: 1.5, delay: 5, maxH: 0.08, drop: true },
  { x: 19, w: 2.0, delay: 12, maxH: 0.13, drop: true },
  { x: 25, w: 1.0, delay: 25, maxH: 0.04, drop: false },
  { x: 28, w: 1.2, delay: 15, maxH: 0.06, drop: false },
  { x: 34, w: 1.8, delay: 3, maxH: 0.16, drop: true },
  { x: 41, w: 1.1, delay: 20, maxH: 0.05, drop: false },
  { x: 45, w: 1.8, delay: 8, maxH: 0.11, drop: true },
  { x: 52, w: 2.4, delay: 14, maxH: 0.15, drop: true },
  { x: 58, w: 0.9, delay: 28, maxH: 0.03, drop: false },
  { x: 65, w: 1.4, delay: 20, maxH: 0.07, drop: true },
  { x: 72, w: 1.7, delay: 6, maxH: 0.10, drop: true },
  { x: 78, w: 1.2, delay: 16, maxH: 0.06, drop: false },
  { x: 82, w: 2.0, delay: 12, maxH: 0.09, drop: true },
  { x: 89, w: 1.5, delay: 9, maxH: 0.14, drop: true },
  { x: 96, w: 1.0, delay: 22, maxH: 0.05, drop: false },
];

const AdAnimation: React.FC<AdAnimationProps> = ({
  backgroundColor = "#A5E6D3",
  transparentBackground = false,
  durationInSeconds = 5,
  topText = "USED BY 6,000+ GHL USERS:",
  topTextSize = 3.5,
  percentageText = "20-30%",
  percentageTextSize = 23,
  highlightText = "More Revenue",
  highlightTextSize = 16.5,
  highlightColor = "#EE3516",
  middleText1 = "From Leads",
  middleText2 = "Guaranteed",
  middleTextSize = 18,
  bottomText = "or you don't pay.",
  bottomTextSize = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Parser safety for background
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timings ---
  // Frame 0: Top text fades in
  const topOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const topY = interpolate(frame, [0, 15], [-20, 0], { extrapolateRight: "clamp" });

  // Frame 15: Percentage pops in
  const percentScale = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12, mass: 0.8 },
  });

  // Frame 30: Highlight text (More Revenue) pops and slightly rotates into place
  const highlightScale = spring({
    frame: frame - 30,
    fps,
    config: { damping: 10, mass: 0.7 },
  });
  const highlightRot = interpolate(frame - 30, [0, 20], [-5, 0], { 
    extrapolateRight: "clamp", 
    extrapolateLeft: "clamp" 
  });

  // Frame 45 & 50: "From Leads" and "Guaranteed" slide up firmly
  const leadsSpring = spring({ frame: frame - 45, fps, config: { damping: 14 } });
  const leadsY = interpolate(leadsSpring, [0, 1], [60, 0]);
  const leadsOpacity = interpolate(frame, [45, 55], [0, 1], { extrapolateRight: "clamp" });

  const guarSpring = spring({ frame: frame - 50, fps, config: { damping: 14 } });
  const guarY = interpolate(guarSpring, [0, 1], [60, 0]);
  const guarOpacity = interpolate(frame, [50, 60], [0, 1], { extrapolateRight: "clamp" });

  // Frame 70: Bottom text fades in
  const botOpacity = interpolate(frame, [70, 85], [0, 1], { extrapolateRight: "clamp" });

  // --- Layout Calculations based on Canvas Width ---
  const styles: Record<string, React.CSSProperties> = {
    top: {
      fontFamily: interFamily,
      fontSize: width * (topTextSize / 100),
      fontWeight: 800,
      letterSpacing: "0.05em",
      color: "#111",
      opacity: topOpacity,
      transform: `translateY(${topY}px)`,
      marginBottom: width * 0.03,
      transition: "none",
      maxWidth: "100%",
      overflowWrap: "break-word",
      whiteSpace: "pre-wrap",
    },
    percentage: {
      fontFamily: interFamily,
      fontSize: width * (percentageTextSize / 100),
      fontWeight: 900,
      letterSpacing: "-0.04em",
      lineHeight: 0.9,
      color: "#0a0a0a",
      transform: `scale(${percentScale})`,
      transformOrigin: "left center",
      transition: "none",
      maxWidth: "100%",
      overflowWrap: "break-word",
      whiteSpace: "pre-wrap",
    },
    highlight: {
      fontFamily: gothicFamily,
      fontSize: width * (highlightTextSize / 100),
      lineHeight: 0.95,
      color: highlightColor,
      transform: `scale(${highlightScale}) rotate(${highlightRot}deg)`,
      transformOrigin: "left center",
      transition: "none",
      textShadow: `2px 2px 0px rgba(0,0,0,0.05)`, // Adds a slight punch mimicking the original ink
      maxWidth: "100%",
      overflowWrap: "break-word",
      whiteSpace: "pre-wrap",
    },
    middle: {
      fontFamily: interFamily,
      fontSize: width * (middleTextSize / 100),
      fontWeight: 900,
      letterSpacing: "-0.03em",
      lineHeight: 0.88,
      color: "#0a0a0a",
      transition: "none",
      maxWidth: "100%",
      overflowWrap: "break-word",
      whiteSpace: "pre-wrap",
    },
    bottom: {
      fontFamily: interFamily,
      fontSize: width * (bottomTextSize / 100),
      fontWeight: 700,
      color: "#111",
      opacity: botOpacity,
      marginTop: width * 0.08,
      letterSpacing: "-0.01em",
      transition: "none",
      maxWidth: "100%",
      overflowWrap: "break-word",
      whiteSpace: "pre-wrap",
    },
  };

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        padding: "8%", // Replaced left/right padding with full 8% padding to guarantee top/bottom containment
        boxSizing: "border-box", // Ensure padding does not push elements out of bounds
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "flex-start",
      }}
    >
      <div style={styles.top}>{topText}</div>
      
      <div style={styles.percentage}>{percentageText}</div>
      
      {/* Wrapped in a relative container to position blood drips beneath the text */}
      <div style={{ ...styles.highlight, position: "relative", display: "inline-block" }}>
        <span style={{ position: "relative", zIndex: 2 }}>{highlightText}</span>
        
        {dripsData.map((drip, i) => {
          // Drops start slightly after the word lands (Frame 30 + delay)
          const startFrame = 30 + drip.delay;
          
          // Animate the streak growing downwards
          const dripLength = interpolate(
            frame, 
            [startFrame, startFrame + 30], 
            [0, width * drip.maxH], 
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          
          // Animate the detached droplet falling further down
          const fallDist = interpolate(
            frame, 
            [startFrame + 30, startFrame + 50], 
            [0, width * 0.15], 
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          
          // Fade out the detached droplet as it falls away
          const dropletOpacity = interpolate(
            frame, 
            [startFrame + 40, startFrame + 50], 
            [1, 0], 
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <React.Fragment key={`drip-${i}`}>
              {/* Main Drip Streak */}
              <div 
                style={{
                  position: "absolute",
                  top: "calc(100% - 0.35em)", // Start just inside the bottom of the letters
                  left: `${drip.x}%`,
                  width: `${drip.w}%`,
                  height: `${dripLength}px`,
                  backgroundColor: highlightColor,
                  borderRadius: "0 0 50px 50px",
                  zIndex: 1, // Stay beneath the text layer
                }} 
              />
              
              {/* Detached Droplet */}
              {drip.drop && frame > startFrame + 30 && (
                <div 
                  style={{
                    position: "absolute",
                    top: `calc(100% - 0.35em + ${dripLength + fallDist}px)`,
                    left: `calc(${drip.x}% - ${drip.w * 0.25}%)`,
                    width: `${drip.w * 1.5}%`,
                    aspectRatio: "1/1",
                    backgroundColor: highlightColor,
                    borderRadius: "50%",
                    zIndex: 1,
                    opacity: dropletOpacity,
                  }} 
                />
              )}
            </React.Fragment>
          );
        })}
      </div>
      
      <div style={{ ...styles.middle, opacity: leadsOpacity, transform: `translateY(${leadsY}px)` }}>
        {middleText1}
      </div>
      
      <div style={{ ...styles.middle, opacity: guarOpacity, transform: `translateY(${guarY}px)` }}>
        {middleText2}
      </div>
      
      <div style={styles.bottom}>{bottomText}</div>
    </AbsoluteFill>
  );
};

export default AdAnimation;